'use strict';

const express = require('express');
const mysql = require('mysql2/promise');
const http = require('http');
const { spawn } = require('child_process');

const PUBLIC_PORT = Number(process.env.PORT || 8080);
const LEGACY_PORT = Number(process.env.LEGACY_PORT || 8081);
const LEGACY_HOST = '127.0.0.1';

const db = mysql.createPool({
  host: process.env.DB_HOST || process.env.MYSQLHOST || '127.0.0.1',
  port: Number(process.env.DB_PORT || process.env.MYSQLPORT || 3306),
  user: process.env.DB_USER || process.env.MYSQLUSER || 'root',
  password: process.env.DB_PASS || process.env.MYSQLPASSWORD || '',
  database: process.env.DB_NAME || process.env.MYSQLDATABASE || 'anythingxpress',
  waitForConnections: true,
  connectionLimit: 8,
  queueLimit: 0,
  decimalNumbers: true,
  charset: 'utf8mb4'
});

function esc(v='') { return String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function money(v) { return `₵${Number(v || 0).toFixed(2)}`; }
function safeSlug(v='') { return String(v).toLowerCase().replace(/[^a-z0-9-]/g,''); }
function netMeta(code='', name='') {
  const c = String(code).toLowerCase();
  if (c === 'mtn') return { key:'mtn', label:'MTN', short:'MTN' };
  if (c === 'telecel' || c === 'vodafone') return { key:'telecel', label:'Telecel', short:'TC' };
  if (c === 'at' || c === 'airteltigo') return { key:'at', label:'AT', short:'AT' };
  return { key:c || 'other', label:name || code || 'Network', short:(name || code || 'N').slice(0,2).toUpperCase() };
}

async function baseBundles() {
  const [rows] = await db.query(`SELECT db.id, db.name, db.size_label, db.size_mb, db.validity_days, db.base_price AS price, n.id network_id, n.name network_name, n.code network_code, n.color network_color FROM data_bundles db JOIN networks n ON n.id=db.network_id WHERE db.is_active=1 AND n.is_active=1 ORDER BY n.id, db.sort_order, db.size_mb`);
  return rows;
}
async function resolveSeller(slugOrRef) {
  const [rows] = await db.query(`SELECT id, merchant_id, role, full_name, store_name, store_description, logo_image, share_image, phone, store_phone, email, referral_code, store_slug FROM agents WHERE is_active=1 AND is_approved=1 AND (store_slug=? OR referral_code=?) LIMIT 1`,[slugOrRef,slugOrRef]);
  return rows[0] || null;
}
async function sellerBundles(seller) {
  if (!seller) return baseBundles();
  let sql, args;
  if (seller.role === 'merchant') {
    sql = `SELECT db.id, db.name, db.size_label, db.size_mb, db.validity_days, COALESCE(NULLIF(mbp.custom_price,0), NULLIF(aap.agent_base_price,0), db.base_price) AS price, n.id network_id, n.name network_name, n.code network_code, n.color network_color FROM data_bundles db JOIN networks n ON n.id=db.network_id LEFT JOIN admin_agent_bundle_prices aap ON aap.bundle_id=db.id AND aap.is_active=1 LEFT JOIN merchant_bundle_prices mbp ON mbp.bundle_id=db.id AND mbp.merchant_id=? AND mbp.is_active=1 WHERE db.is_active=1 AND n.is_active=1 ORDER BY n.id, db.sort_order, db.size_mb`;
    args = [seller.merchant_id || seller.id];
  } else {
    sql = `SELECT db.id, db.name, db.size_label, db.size_mb, db.validity_days, COALESCE(NULLIF(abp.custom_price,0), NULLIF(mbp.custom_price,0), NULLIF(aap.agent_base_price,0), db.base_price) AS price, n.id network_id, n.name network_name, n.code network_code, n.color network_color FROM data_bundles db JOIN networks n ON n.id=db.network_id LEFT JOIN admin_agent_bundle_prices aap ON aap.bundle_id=db.id AND aap.is_active=1 LEFT JOIN merchant_bundle_prices mbp ON mbp.bundle_id=db.id AND mbp.merchant_id=? AND mbp.is_active=1 LEFT JOIN agent_bundle_prices abp ON abp.bundle_id=db.id AND abp.agent_id=? AND abp.is_active=1 WHERE db.is_active=1 AND n.is_active=1 ORDER BY n.id, db.sort_order, db.size_mb`;
    args = [seller.merchant_id || 0, seller.id];
  }
  const [rows] = await db.query(sql,args);
  return rows.filter(r => Number(r.price) > 0);
}

